def _request_host_from_context(context: dict[str, Any]) -> str | None:
    request = context.get("request")
    if not request:
        return None

    try:
        return request.get_host()
    except Exception:
        meta = getattr(request, "META", {}) or {}
        host = meta.get("HTTP_HOST") or meta.get("SERVER_NAME")
        return str(host) if host else None


def _viewer_can_access_arrive_by_fields(
    context: dict[str, Any],
    obj: Event,
) -> bool:
    visibility_map = context.get("arrive_by_visibility_map")
    if visibility_map is not None:
        return bool(visibility_map.get(str(obj.id), False))

    request = context.get("request")
    user = getattr(request, "user", None)
    return can_user_view_arrive_by(obj, user)


def _serialize_arrive_by(
    context: dict[str, Any],
    obj: Event,
) -> dict[str, object] | None:
    request = context.get("request")
    user = getattr(request, "user", None)
    direct_family_ids = context.get("viewer_direct_family_ids")
    return get_arrive_by_payload(
        obj,
        user=user,
        direct_family_ids=direct_family_ids,
    )


def _resolve_tentative_share_from_context(
    context: dict[str, Any],
    obj: Event,
) -> Any | None:
    request = context.get("request")
    if not request or not request.user.is_authenticated:
        return None
    if obj.event_status != Event.STATUS_TENTATIVE:
        return None

    share_map = context.get("tentative_share_map")
    if share_map is not None:
        return share_map.get(str(obj.id))

    from users.models import FamilyMembership

    from .sharing_models import TentativeEventShare

    user = cast(User, request.user)
    family_ids = FamilyMembership.objects.filter(user=user).values_list(
        "family_id", flat=True
    )
    return (
        TentativeEventShare.objects.filter(event=obj, target_family_id__in=family_ids)
        .select_related("source_family")
        .first()
    )


def _get_event_calendar_from_context(
    context: dict[str, Any],
    obj: Event,
) -> ExternalCalendarAccount | InternalCalendar | None:
    from users.utils import _build_external_calendar_lookup

    external_calendars_dict = context.get("external_calendars_dict") or {}
    internal_calendars_dict = context.get("internal_calendars_dict") or {}
    external_calendar_lookup = context.get("external_calendar_lookup")
    if external_calendar_lookup is None:
        external_calendar_lookup = _build_external_calendar_lookup(
            external_calendars_dict
        )
        context["external_calendar_lookup"] = external_calendar_lookup

    calendar = None
    if getattr(obj, "internal_calendar_id", None):
        calendar = internal_calendars_dict.get(obj.internal_calendar_id)

    if not calendar and getattr(obj, "is_external", False) and obj.calendar_id:
        calendar = external_calendar_lookup.get(str(obj.calendar_id))

    if not calendar and getattr(obj, "internal_calendar", None):
        calendar = obj.internal_calendar

    return calendar


def _load_external_calendar_for_event(
    obj: Event,
) -> ExternalCalendarAccount | InternalCalendar | None:
    if not getattr(obj, "is_external", False) or not obj.calendar_id:
        return None

    try:
        from calendars.models import ExternalCalendarAccount

        prefetch_fields = (
            "associated_users__profile",
            "associated_users__child_profile",
            "associated_users__socialaccount_set",
            "associated_children",
            "user__socialaccount_set",
            "user__child_profile",
        )
        try:
            calendar_pk = int(obj.calendar_id)
            return (
                ExternalCalendarAccount.objects.prefetch_related(*prefetch_fields)
                .select_related("user__profile")
                .filter(id=calendar_pk)
                .first()
            )
        except (ValueError, TypeError):
            return (
                ExternalCalendarAccount.objects.prefetch_related(*prefetch_fields)
                .select_related("user__profile")
                .filter(calendar_id=obj.calendar_id)
                .first()
            )
    except Exception as e:
        logger.warning(f"DB fallback for event {obj.id} calendar lookup failed: {e}")
        return None


def _serialize_calendar_associated_users(
    calendar: ExternalCalendarAccount | InternalCalendar,
    *,
    request_host: str | None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> list[dict[str, Any]]:
    user_list: list[dict[str, Any]] = []

    if hasattr(calendar, "associated_users"):
        for user in calendar.associated_users.all():
            if not user.is_active:
                continue

            user_list.append(
                {
                    "id": user.id,
                    "name": user.get_full_name() or user.username,
                    "avatar": _resolve_user_avatar(
                        user,
                        request_host=request_host,
                        cache=cache,
                    ),
                }
            )

    if hasattr(calendar, "associated_children"):
        for child in calendar.associated_children.all():
            avatar_url = None
            if child.profile_picture:
                avatar_url = _resolve_profile_picture_avatar(
                    child.profile_picture,
                    request_host=request_host,
                    cache=cache,
                )

            user_list.append(
                {
                    "id": f"child_{child.id}",
                    "name": f"{child.first_name} {child.last_name}",
                    "avatar": avatar_url,
                }
            )

    return user_list


def _calendar_kind(calendar: ExternalCalendarAccount | InternalCalendar) -> str:
    model_name = getattr(getattr(calendar, "_meta", None), "model_name", "")
    return "external" if model_name == "externalcalendaraccount" else "internal"


def _associated_user_cache_key(
    calendar: ExternalCalendarAccount | InternalCalendar,
    request_host: str | None,
) -> str:
    return (
        f"{_calendar_kind(calendar)}:"
        f"{getattr(calendar, 'pk', None)}:"
        f"{request_host or ''}"
    )


class EventOwnershipMixin:
    """Adds resolved ownership metadata to event serializers."""

    display_member = serializers.SerializerMethodField()
    ownership_source = serializers.SerializerMethodField()
    source_calendar = serializers.SerializerMethodField()
    resolved_colors = serializers.SerializerMethodField()

    def get_display_member(self, obj: Event) -> dict[str, Any] | None:
        ownership = self._get_resolved_ownership(obj)
        return ownership["display_member"]

    def get_ownership_source(self, obj: Event) -> str:
        ownership = self._get_resolved_ownership(obj)
        return ownership["ownership_source"]

    def get_source_calendar(self, obj: Event) -> dict[str, Any] | None:
        ownership = self._get_resolved_ownership(obj)
        return ownership["source_calendar"]

    def get_resolved_colors(self, obj: Event) -> dict[str, Any]:
        ownership = self._get_resolved_ownership(obj)
        return ownership["resolved_colors"]

    def _get_resolved_ownership(self, obj: Event) -> dict[str, Any]:
        # Cache per-instance to avoid re-resolving for each field
        cache_attr = "_resolved_ownership_cache"
        if not hasattr(self, cache_attr):
            setattr(self, cache_attr, {})
        ownership_cache = getattr(self, cache_attr)
        if obj.pk not in ownership_cache:
            from users.event_ownership import resolve_event_ownership

            context: dict[str, Any] = cast(Any, self).context
            request_host = _request_host_from_context(context)
            avatar_cache = getattr(context.get("request"), "_event_avatar_cache", None)
            ownership_cache[obj.pk] = resolve_event_ownership(
                obj,
                external_calendars_dict=context.get("external_calendars_dict"),
                external_calendar_lookup=context.get("external_calendar_lookup"),
                internal_calendars_dict=context.get("internal_calendars_dict"),
                request_host=request_host,
                cache=avatar_cache,
            )
        return ownership_cache[obj.pk]


class EventGroupMetadataMixin:
    family_group_kind = serializers.SerializerMethodField()
    family_group_name = serializers.SerializerMethodField()
    source_group_plan = serializers.SerializerMethodField()

    def get_family_group_name(self, obj: Event) -> str | None:
        family_group = getattr(obj, "family_group", None)
        if family_group:
            return family_group.name
        return None

    def get_family_group_kind(self, obj: Event) -> str | None:
        family_group = getattr(obj, "family_group", None)
        if not family_group:
            return None
        group_type = getattr(family_group, "group_type", None)
        if group_type:
            return group_type.type
        return None

    def get_source_group_plan(self, obj: Event) -> dict[str, Any] | None:
        plan = getattr(obj, "source_group_plan", None)
        if not plan:
            return None

        family_group = getattr(plan, "family_group", None)
        group_type = getattr(getattr(family_group, "group_type", None), "type", None)

        return {
            "id": str(plan.id),
            "title": plan.title,
            "template": plan.template,
            "status": plan.status,
            "group": {
                "id": str(family_group.id) if family_group else None,
                "name": family_group.name if family_group else None,
                "group_kind": group_type,
            },
        }

    def _serialize_participating_families(self, obj: Event) -> list[dict[str, Any]]:
        if obj.event_status != Event.STATUS_CONFIRMED:
            return []

        from events.participation import visible_participations_for_viewer

        context: dict[str, Any] = cast(Any, self).context
        request = context.get("request")
        viewer = getattr(request, "user", None)
        participations = visible_participations_for_viewer(obj, viewer)
        serializer = EventParticipationSerializer(
            participations,
            many=True,
            context=context,
        )
        return [cast(dict[str, Any], item) for item in serializer.data]


class EventParticipationSerializer(serializers.ModelSerializer[EventFamilyGroups]):
    family = FamilyGroupSerializerLite(source="familygroup", read_only=True)
    source_group = serializers.SerializerMethodField()

    class Meta:
        model = EventFamilyGroups
        fields = [
            "id",
            "family",
            "status",
            "invitation_source",
            "source_group",
            "joined_at",
            "responded_at",
        ]
        read_only_fields = fields

    def get_source_group(self, obj: EventFamilyGroups) -> dict[str, Any] | None:
        if not obj.source_group_id or obj.source_group is None:
            return None

        group_type = getattr(
            getattr(obj.source_group, "group_type", None), "type", None
        )
        return {
            "id": str(obj.source_group.id),
            "name": obj.source_group.name,
            "group_kind": group_type,
        }


class EventInvitableFamilySerializer(serializers.Serializer):
    family = FamilyGroupSerializerLite(read_only=True)
    source_group_name = serializers.SerializerMethodField()

    def get_source_group_name(self, obj: dict[str, object]) -> str | None:
        source_group_name = obj.get("source_group_name")
        return None if source_group_name is None else str(source_group_name)

    def to_representation(self, instance: dict[str, object]) -> dict[str, object]:
        data = super().to_representation(instance)
        data["source"] = str(instance["source"])
        return data


class EventSerializer(
    EventOwnershipMixin, EventGroupMetadataMixin, serializers.ModelSerializer[Event]
):
    location = serializers.CharField(max_length=255, required=False, allow_blank=True)
    title = serializers.CharField(max_length=200, required=True)
    associated_users = serializers.SerializerMethodField()
    arrive_by = serializers.SerializerMethodField()
    member_color = serializers.SerializerMethodField()
    is_shared_tentative = serializers.SerializerMethodField()
    shared_from_family = serializers.SerializerMethodField()
    participating_families = serializers.SerializerMethodField()
    family_group_name = serializers.SerializerMethodField()
    family_group_kind = serializers.SerializerMethodField()
    source_group_plan = serializers.SerializerMethodField()
    display_member = serializers.SerializerMethodField()
    ownership_source = serializers.SerializerMethodField()
    source_calendar = serializers.SerializerMethodField()
    resolved_colors = serializers.SerializerMethodField()

    class Meta:
        model = Event
        fields = "__all__"
        read_only_fields = [
            "creator",
            "created_at",
            "updated_at",
            "source_group_plan",
        ]

    def get_is_shared_tentative(self, obj: Event) -> bool:
        return _resolve_tentative_share_from_context(self.context, obj) is not None

    def get_shared_from_family(self, obj: Event) -> dict[str, str] | None:
        share = _resolve_tentative_share_from_context(self.context, obj)
        if share:
            return {"id": str(share.source_family.id), "name": share.source_family.name}
        return None

    def get_member_color(self, obj: Event) -> str:
        """
        Get the color of the family member who owns this event.
        - For synced events: Use associated user's color, fallback to calendar owner
        - For manual events: Use creator's color

        Uses pre-fetched calendar data from context when available to avoid N+1 queries.
        """
        from users.utils import get_event_member_color

        # Get pre-fetched calendar data from context (if available)
        external_calendars_dict = self.context.get("external_calendars_dict")
        internal_calendars_dict = self.context.get("internal_calendars_dict")

        return get_event_member_color(
            obj,
            external_calendars_dict=external_calendars_dict,
            internal_calendars_dict=internal_calendars_dict,
        )

    def get_associated_users(self, obj: Event) -> list[dict[str, Any]]:
        """Get users associated with this event's calendar"""
        request_host = _request_host_from_context(self.context)
        calendar = _get_event_calendar_from_context(self.context, obj)
        if not calendar:
            calendar = _load_external_calendar_for_event(obj)
        if calendar:
            user_list = _serialize_calendar_associated_users(
                calendar,
                request_host=request_host,
            )
            if user_list:
                logger.debug(
                    f"Event {obj.id} returning {len(user_list)} associated users/children"
                )
                return user_list

        logger.debug(
            f"Event {obj.id} no associated users/children found "
            f"(calendar={calendar}, is_external={getattr(obj, 'is_external', None)}, "
            f"calendar_id={getattr(obj, 'calendar_id', None)})"
        )
        return []

    def get_arrive_by(self, obj: Event) -> dict[str, object] | None:
        return _serialize_arrive_by(self.context, obj)

    def validate_title(self, value: str) -> str:
        """Validate title length and content"""
        if len(value.strip()) == 0:
            raise serializers.ValidationError("Title cannot be empty")
        return value.strip()

    def validate_location(self, value: str | None) -> str | None:
        """Validate location length and content"""
        if value and len(value) > 255:
            raise serializers.ValidationError("Location must be 255 characters or less")
        return value.strip() if value else value

    def validate_family_group(self, value: FamilyGroup | None) -> FamilyGroup | None:
        """
        Validate that events cannot be created in META (network) families.
        Events should only be created in IMMEDIATE families and become visible
        to connected META families through the meta-family relationship.
        """
        from users.models import FamilyGroupType

        if value is None:
            return value

        # Check if this family is a META type
        try:
            family_type = FamilyGroupType.objects.filter(family=value).first()
            if family_type and family_type.type == "META":
                raise serializers.ValidationError(
                    "Events cannot be created directly in a family network. "
                    "Please select your immediate family instead. Events will "
                    "automatically be visible to connected network families."
                )
        except serializers.ValidationError:
            # Re-raise validation errors
            raise
        except Exception as e:
            # If we can't check the type, allow the operation and log the issue
            # (FamilyGroupType may not exist for old families)
            logger.warning(
                f"Could not validate family group type for family {value.id}: {e}"
            )

        return value

    def validate(self, attrs):
        attrs = super().validate(attrs)

        from users.models import FamilyMembership

        family_group = attrs.get(
            "family_group", getattr(self.instance, "family_group", None)
        )
        assigned_user = attrs.get(
            "assigned_user", getattr(self.instance, "assigned_user", None)
        )
        assigned_child = attrs.get(
            "assigned_child", getattr(self.instance, "assigned_child", None)
        )

        assignee_errors: dict[str, list[str]] = {}
        if assigned_user and assigned_child:
            message = "Choose either a family member or a child for event assignment."
            assignee_errors["assigned_user"] = [message]
            assignee_errors["assigned_child"] = [message]
        elif (assigned_user or assigned_child) and family_group is None:
            assignee_errors["family_group"] = [
                "Assigned events must belong to a family."
            ]
        elif (
            assigned_user
            and not FamilyMembership.objects.filter(
                user=assigned_user,
                family=family_group,
                is_active=True,
            ).exists()
        ):
            assignee_errors["assigned_user"] = [
                "Assigned family member must belong to this family."
            ]
        elif assigned_child and assigned_child.family_id != family_group.id:
            assignee_errors["assigned_child"] = [
                "Assigned child must belong to this family."
            ]

        if assignee_errors:
            raise serializers.ValidationError(assignee_errors)

        mode = attrs.get(
            "arrive_by_mode",
            getattr(self.instance, "arrive_by_mode", Event.ArriveByMode.AUTO),
        )
        minutes_before_start = attrs.get(
            "arrive_by_minutes_before_start",
            getattr(self.instance, "arrive_by_minutes_before_start", None),
        )

        if mode == Event.ArriveByMode.OFF:
            attrs["arrive_by_minutes_before_start"] = None
            return attrs

        if minutes_before_start is not None:
            if minutes_before_start <= 0:
                raise serializers.ValidationError(
                    {
                        "arrive_by_minutes_before_start": "Arrive-by minutes must be greater than zero when provided."
                    }
                )
            if minutes_before_start > MAX_ARRIVE_BY_MINUTES:
                raise serializers.ValidationError(
                    {
                        "arrive_by_minutes_before_start": "Arrive-by minutes must be 12 hours or less."
                    }
                )

        return attrs

    def get_participating_families(self, obj: Event) -> list[dict[str, Any]]:
        return self._serialize_participating_families(obj)

    def create(self, validated_data):
        from events.services.participation_resolver import EventParticipationResolver

        with transaction.atomic():
            instance = super().create(validated_data)
            request = self.context.get("request")
            actor = cast(User, getattr(request, "user", instance.creator))
            if instance.event_status == Event.STATUS_CONFIRMED:
                EventParticipationResolver().sync_owner_participation(
                    instance, actor=actor
                )
            return instance

    def update(self, instance: Event, validated_data):
        from events.services.participation_resolver import EventParticipationResolver

        with transaction.atomic():
            updated = super().update(instance, validated_data)
            request = self.context.get("request")
            actor = cast(User, getattr(request, "user", updated.creator))
            if updated.event_status == Event.STATUS_CONFIRMED:
                EventParticipationResolver().sync_owner_participation(
                    updated, actor=actor
                )
            return updated


