    def get_is_shared_tentative(self, obj: Event) -> bool:
        return _resolve_tentative_share_from_context(self.context, obj) is not None

    def get_shared_from_family(self, obj: Event) -> dict[str, str] | None:
        share = _resolve_tentative_share_from_context(self.context, obj)
        if share:
            return {"id": str(share.source_family.id), "name": share.source_family.name}
        return None

    def _get_calendar_from_context(
        self, obj: Event
    ) -> ExternalCalendarAccount | InternalCalendar | None:
        """
        Resolve the calendar for an event using preloaded dictionaries to avoid DB hits.
        Falls back to the prefetched internal_calendar instance if available.
        """
        return _get_event_calendar_from_context(self.context, obj)

    def get_member_color(self, obj: Event) -> str:
        """
        Get the color of the family member who owns this event.
        - For synced events: Use associated user's color, fallback to calendar owner
        - For manual events: Use creator's color

        Uses pre-fetched calendar data from context when available to avoid N+1 queries.
        """
        from users.utils import get_event_member_color

        # Get pre-fetched calendar data from context (if available)
        external_calendars_dict = self.context.get("external_calendars_dict")
        internal_calendars_dict = self.context.get("internal_calendars_dict")

        return get_event_member_color(
            obj,
            external_calendars_dict=external_calendars_dict,
            internal_calendars_dict=internal_calendars_dict,
        )

    def get_associated_users(self, obj: Event) -> list[dict[str, Any]]:
        """Get users associated with this event's calendar"""
        request_host = _request_host_from_context(self.context)
        calendar = self._get_calendar_from_context(obj)
        used_db_fallback = False

        # DB fallback if context dict missed this calendar
        if not calendar:
            calendar = _load_external_calendar_for_event(obj)
            used_db_fallback = bool(calendar)
            if calendar:
                logger.debug(
                    f"Event {obj.id}: used DB fallback for calendar {calendar.id}"
                )

        if calendar:
            cache_attr = "_associated_users_cache"
            if not hasattr(self, cache_attr):
                setattr(self, cache_attr, {})
            user_list_cache = cast(
                dict[str, list[dict[str, Any]]], getattr(self, cache_attr)
            )
            cache_key = _associated_user_cache_key(calendar, request_host)
            if cache_key in user_list_cache:
                return user_list_cache[cache_key]

            avatar_cache = getattr(
                self.context.get("request"), "_event_avatar_cache", None
            )

            with child_span(
                "api.events.serialize.associated_users",
                calendar_kind=_calendar_kind(calendar),
                used_db_fallback=used_db_fallback,
            ) as associated_users_span:
                user_list = _serialize_calendar_associated_users(
                    calendar,
                    request_host=request_host,
                    cache=avatar_cache,
                )
                set_span_attributes(
                    associated_users_span,
                    serialized_user_count=len(user_list),
                )
            user_list_cache[cache_key] = user_list

            if user_list:
                logger.debug(
                    f"Event {obj.id} returning {len(user_list)} associated users/children"
                )
                return user_list

        logger.debug(
            f"Event {obj.id} no associated users/children found "
            f"(calendar={calendar}, is_external={getattr(obj, 'is_external', None)}, "
            f"calendar_id={getattr(obj, 'calendar_id', None)})"
        )
        return []

    def get_user_reminder(self, obj: Event) -> dict[str, Any] | None:
        """
        Return the authenticated user's reminder metadata for the current event.

        The view prefetches reminders to minimize queries; if that prefetched
        data is unavailable we fall back to a filtered lookup.
        """
        request = self.context.get("request")
        user = getattr(request, "user", None)

        if not user or not user.is_authenticated:
            return None

        reminder = None

        # Use precomputed reminder map when available
        reminder_map = self.context.get("user_reminders_map") or {}
        if str(obj.id) in reminder_map:
            reminder = reminder_map[str(obj.id)]
            if reminder is None:
                return None

        # Prefetched reminders attached in the viewset
        if (
            not reminder
            and hasattr(obj, "_current_user_reminders")
            and obj._current_user_reminders
        ):
            reminder = obj._current_user_reminders[0]
        elif not reminder:
            with child_span("api.events.serialize.user_reminder") as reminder_span:
                reminder = obj.reminders.filter(user=user).first()
                set_span_attributes(
                    reminder_span,
                    reminder_found=reminder is not None,
                )

        if not reminder:
            return None

        return EventReminderSerializer(reminder).data

    def get_arrive_by(self, obj: Event) -> dict[str, object] | None:
        return _serialize_arrive_by(self.context, obj)

    def get_arrive_by_mode(self, obj: Event) -> str | None:
        if not _viewer_can_access_arrive_by_fields(self.context, obj):
            return None
        return obj.arrive_by_mode

    def get_arrive_by_minutes_before_start(self, obj: Event) -> int | None:
        if not _viewer_can_access_arrive_by_fields(self.context, obj):
            return None
        return obj.arrive_by_minutes_before_start

    def _geocode_if_needed(self, obj: Event) -> dict[str, float] | None:
        """Helper to geocode location once and cache result."""
        # Check if we've already geocoded this object in this serializer instance
        if not hasattr(self, "_geocoded_cache"):
            self._geocoded_cache: dict[str, dict[str, float] | None] = {}

        obj_id = str(obj.id)
        if obj_id in self._geocoded_cache:
            return self._geocoded_cache[obj_id]

        # If coordinates already exist, return them
        if obj.latitude and obj.longitude:
            result = {"lat": obj.latitude, "lng": obj.longitude}
            self._geocoded_cache[obj_id] = result
            return result

        # Try to geocode if location exists but coordinates don't
        if obj.location:
            try:
                from .geocoding import GeocodingService

                with child_span(
                    "api.events.serialize.geocode_if_needed"
                ) as geocode_span:
                    coords = GeocodingService.geocode_address(obj.location)
                    set_span_attributes(
                        geocode_span,
                        geocoded=coords is not None,
                    )
                if coords:
                    # coords is a tuple (latitude, longitude)
                    lat, lng = coords
                    # Update the event with coordinates (without triggering signals)
                    # nosemgrep: clancal.security.event-objects-bypass-secure-manager
                    Event.objects.filter(pk=obj.pk).update(latitude=lat, longitude=lng)
                    # Store as dict for consistency with the rest of the method
                    result = {"lat": lat, "lng": lng}
                    self._geocoded_cache[obj_id] = result
                    return result
            except Exception as e:
                logger.debug(f"Failed to geocode location for event {obj.id}: {e}")

        self._geocoded_cache[obj_id] = None
        return None

    def get_latitude(self, obj: Event) -> float | None:
        """Get latitude, geocoding on-the-fly if needed."""
        coords = self._geocode_if_needed(obj)
        return coords["lat"] if coords else None

    def get_longitude(self, obj: Event) -> float | None:
        """Get longitude, geocoding on-the-fly if needed."""
        coords = self._geocode_if_needed(obj)
        return coords["lng"] if coords else None

    def get_show_nearby_restaurants(self, obj: Event) -> bool:
        """
        Determine if nearby restaurants should be shown for this event.
        Priority: event override > calendar setting > default (True for legacy events)
        """
        # Event-level override takes precedence
        if obj.show_nearby_restaurants_override is not None:
            return obj.show_nearby_restaurants_override

        # Check calendar setting
        calendar = self._get_calendar_from_context(obj)

        if calendar and hasattr(calendar, "show_nearby_restaurants"):
            return calendar.show_nearby_restaurants

        # Default: show restaurants for legacy events
        return True

    def get_participating_families(self, obj: Event):
        return self._serialize_participating_families(obj)


