    def _get_originating_group_plan_proposal(self, obj: GroupPlan):
        from family_agent.models import FamilyAgentProposal

        cache = getattr(self, "_originating_group_plan_proposal_cache", None)
        if cache is None:
            cache = {}
            self._originating_group_plan_proposal_cache = cache

        cache_key = str(obj.id)
        if cache_key not in cache:
            cache[cache_key] = (
                FamilyAgentProposal.objects.select_related("run", "thread")
                .filter(
                    proposal_type=FamilyAgentProposal.Type.GROUP_PLAN,
                    result_ref_json__plan_id=cache_key,
                )
                .order_by("-updated_at")
                .first()
            )
        return cache[cache_key]

    def _build_group_plan_capture_photo_artifact(
        self, capture: Any
    ) -> dict[str, Any] | None:
        photo = getattr(capture, "photo", None)
        if not photo:
            return None

        try:
            photo_url = str(photo.url)
        except Exception:
            return None

        request = self.context.get("request")
        if request is not None:
            try:
                photo_url = request.build_absolute_uri(photo_url)
            except Exception:
                pass

        return {
            "preview_url": photo_url,
            "thumbnail_url": None,
            "original_filename": photo.name.rsplit("/", 1)[-1] if photo.name else "",
        }

    def _build_group_plan_attachment_artifact(
        self, attachment: Any
    ) -> dict[str, Any] | None:
        from core.private_media import PrivateMediaStorageService

        preview_url = PrivateMediaStorageService.generate_download_url(
            attachment.object_key,
            request_host=_request_host_from_context(self.context),
            storage_alias=attachment.storage_alias,
        )
        if not preview_url:
            return None

        thumbnail_url = None
        if attachment.thumbnail_object_key:
            thumbnail_url = PrivateMediaStorageService.generate_download_url(
                attachment.thumbnail_object_key,
                request_host=_request_host_from_context(self.context),
                storage_alias=attachment.storage_alias,
            )

        return {
            "preview_url": preview_url,
            "thumbnail_url": thumbnail_url,
            "original_filename": attachment.original_filename,
        }

    def _get_originating_capture(self, proposal: Any) -> Any | None:
        from organize.models import InboxCapture

        trigger_message = getattr(proposal.run, "trigger_message", None)
        if trigger_message is None:
            return None

        context_payload = trigger_message.context_json or {}
        capture_id = str(context_payload.get("capture_id") or "").strip()
        if not capture_id:
            return None

        cache = getattr(self, "_originating_group_plan_capture_cache", None)
        if cache is None:
            cache = {}
            self._originating_group_plan_capture_cache = cache

        if capture_id not in cache:
            cache[capture_id] = (
                InboxCapture.objects.filter(
                    id=capture_id, family=proposal.thread.family
                )
                .only("id", "photo", "normalized_payload")
                .first()
            )
        return cache[capture_id]

    def get_planner_artifacts(self, obj: GroupPlan) -> dict[str, Any] | None:
        from family_agent.models import FamilyAgentMessage

        proposal = self._get_originating_group_plan_proposal(obj)
        if proposal is None:
            return None

        links: list[dict[str, Any]] = []
        seen_urls: set[str] = set()

        def add_link(url: Any, *, title: Any = None) -> None:
            normalized_url = str(url or "").strip()
            if not normalized_url or normalized_url in seen_urls:
                return

            seen_urls.add(normalized_url)
            link_payload: dict[str, Any] = {"url": normalized_url}
            normalized_title = str(title or "").strip()
            if normalized_title:
                link_payload["title"] = normalized_title
            links.append(link_payload)

        capture = self._get_originating_capture(proposal)
        if capture is not None:
            capture_payload = capture.normalized_payload or {}
            add_link(
                capture_payload.get("source_url"),
                title=capture_payload.get("preview_title")
                or capture_payload.get("source_domain"),
            )

        assistant_message = (
            proposal.run.messages.filter(role=FamilyAgentMessage.Role.ASSISTANT)
            .order_by("-created_at")
            .first()
        )
        if assistant_message is not None and isinstance(
            assistant_message.citations_json, list
        ):
            for citation in assistant_message.citations_json:
                if not isinstance(citation, dict):
                    continue
                add_link(citation.get("url"), title=citation.get("title"))

        image = (
            self._build_group_plan_capture_photo_artifact(capture)
            if capture is not None
            else None
        )
        if image is None:
            trigger_message = getattr(proposal.run, "trigger_message", None)
            if trigger_message is not None:
                attachment = trigger_message.attachments.order_by(
                    "display_order", "created_at"
                ).first()
                if attachment is not None:
                    image = self._build_group_plan_attachment_artifact(attachment)

        if not links and image is None:
            return None

        return {
            "links": links,
            "image": image,
        }

    def get_coordination_review(self, obj: GroupPlan) -> dict[str, Any] | None:
        proposal = self._get_originating_group_plan_proposal(obj)
        if proposal is None:
            return None

        payload = proposal.payload_json or {}
        coordination_review = payload.get("coordination_review")
        if not isinstance(coordination_review, dict):
            return None
        return coordination_review

    def _validate_instance_update(self, attrs):
        attrs = super().validate(attrs)
        if not self.instance:
            return attrs

        if (
            "family_group" in attrs
            and attrs["family_group"] != self.instance.family_group
        ):
            raise serializers.ValidationError(
                {"group": "Group cannot be changed once a plan is created."}
            )

        if "mode" in attrs and attrs["mode"] != self.instance.mode:
            raise serializers.ValidationError(
                {"mode": "Planning mode cannot be changed once a plan is created."}
            )

        option_update_requested = any(
            field in attrs
            for field in ("plan_options", "time_options", "choice_options")
        )
        if option_update_requested and (
            self.instance.option_responses.exists()
            or self.instance.availability_responses.exists()
            or self.instance.choice_responses.exists()
        ):
            raise serializers.ValidationError(
                {
                    "plan_options": (
                        "Options cannot be changed once responses have been submitted."
                    )
                }
            )

        mode = attrs.get("mode", self.instance.mode)
        plan_options = attrs.get("plan_options")
        time_options = attrs.get("time_options")
        choice_options = attrs.get("choice_options")

        if mode == "LEGACY_SEPARATE":
            if plan_options is not None:
                raise serializers.ValidationError(
                    {
                        "plan_options": (
                            "Unified plan options are only available for LINKED or TIME_ONLY plans."
                        )
                    }
                )
        else:
            if time_options is not None or choice_options is not None:
                raise serializers.ValidationError(
                    {
                        "plan_options": (
                            "Use plan_options for LINKED and TIME_ONLY plans instead of separate time and choice options."
                        )
                    }
                )

        return attrs

    def validate(self, attrs):
        attrs = super().validate(attrs)
        mode = attrs.get("mode", getattr(self.instance, "mode", "LEGACY_SEPARATE"))
        plan_options = attrs.get("plan_options")
        time_options = attrs.get("time_options")
        choice_options = attrs.get("choice_options")

        if not self.instance:
            if mode == "LEGACY_SEPARATE":
                if plan_options is not None:
                    raise serializers.ValidationError(
                        {
                            "plan_options": (
                                "Unified plan options are only available for LINKED or TIME_ONLY plans."
                            )
                        }
                    )
            else:
                if not plan_options:
                    raise serializers.ValidationError(
                        {
                            "plan_options": (
                                "Add at least one plan option for LINKED or TIME_ONLY plans."
                            )
                        }
                    )
                if time_options is not None or choice_options is not None:
                    raise serializers.ValidationError(
                        {
                            "plan_options": (
                                "Use plan_options for LINKED and TIME_ONLY plans instead of separate time and choice options."
                            )
                        }
                    )
            return attrs

        return self._validate_instance_update(attrs)

    def create(self, validated_data):
        plan_options = validated_data.pop("plan_options", [])
        time_options = validated_data.pop("time_options", [])
        choice_options = validated_data.pop("choice_options", [])
        with transaction.atomic():
            plan = GroupPlan.objects.create(**validated_data)
            for plan_option in plan_options:
                GroupPlanOption.objects.create(plan=plan, **plan_option)
            for time_option in time_options:
                GroupPlanTimeOption.objects.create(plan=plan, **time_option)
            for choice_option in choice_options:
                GroupPlanChoiceOption.objects.create(plan=plan, **choice_option)
        return plan

    def update(self, instance, validated_data):
        plan_options = validated_data.pop("plan_options", None)
        time_options = validated_data.pop("time_options", None)
        choice_options = validated_data.pop("choice_options", None)
        with transaction.atomic():
            instance = super().update(instance, validated_data)
            if plan_options is not None:
                instance.plan_options.all().delete()
                for plan_option in plan_options:
                    GroupPlanOption.objects.create(plan=instance, **plan_option)
            if time_options is not None:
                instance.time_options.all().delete()
                for time_option in time_options:
                    GroupPlanTimeOption.objects.create(plan=instance, **time_option)
            if choice_options is not None:
                instance.choice_options.all().delete()
                for choice_option in choice_options:
                    GroupPlanChoiceOption.objects.create(plan=instance, **choice_option)
        return instance


