class MediaListSerializer(serializers.ModelSerializer[EventMedia]):
    """Lightweight serializer for media list views"""

    file_url = serializers.SerializerMethodField()
    thumbnail_url = serializers.SerializerMethodField()
    uploaded_by = UserCompactSerializer(read_only=True)
    event = EventCompactSerializer(read_only=True)
    tags = serializers.SerializerMethodField()

    class Meta:
        model = EventMedia
        fields = [
            "id",
            "media_type",
            "file_url",
            "thumbnail_url",
            "caption",
            "tags",
            "width",
            "height",
            "duration",
            "uploaded_by",
            "uploaded_at",
            "event",
        ]

    def get_tags(self, obj: EventMedia) -> list[str]:
        """Convert TaggableManager to list of tag names"""
        return list(obj.tags.names())

    def __init__(self, *args: Any, **kwargs: Any) -> None:
        """Initialize serializer and create MediaStorageService instance once"""
        super().__init__(*args, **kwargs)
        # Initialize MediaStorageService once for reuse across all items
        try:
            from .services import MediaStorageService

            self._media_service: MediaStorageService | None = MediaStorageService()
        except ImportError:
            logger.error("Failed to import MediaStorageService during serializer init")
            self._media_service = None

    def _get_request_host(self) -> str | None:
        request = self.context.get("request")
        if not request:
            return None

        try:
            return request.get_host()
        except Exception:
            return None

    def get_file_url(self, obj: EventMedia) -> str | dict[str, Any]:
        """Generate pre-signed URL for the media file with proper error handling"""

        # Check if service was successfully initialized
        if not self._media_service:
            logger.error(f"MediaStorageService not available for media {obj.id}")
            return {"error": "Media service unavailable", "media_id": str(obj.id)}

        try:
            url = self._media_service.generate_presigned_url(
                obj.file_key,
                request_host=self._get_request_host(),
            )

            # Validate the URL was generated successfully
            if not url:
                logger.warning(
                    f"Pre-signed URL generation returned None for media {obj.id} "
                    f"with key {obj.file_key}"
                )
                # Return a placeholder URL or message for the frontend
                return {
                    "error": "URL temporarily unavailable",
                    "retry_after": 60,  # Suggest retry after 60 seconds
                    "media_id": str(obj.id),
                }

            return url

        except Exception as e:
            logger.error(
                f"Unexpected error generating file URL for media {obj.id}: {str(e)}",
                exc_info=True,  # Include stack trace for debugging
            )
            # Return structured error response for frontend handling
            return {
                "error": "Failed to generate media URL",
                "media_id": str(obj.id),
                "retry_after": 30,
            }

    def get_thumbnail_url(self, obj: EventMedia) -> str | None:
        """Generate pre-signed URL for the thumbnail with proper error handling"""
        if not obj.thumbnail_key:
            return None

        # Check if service was successfully initialized
        if not self._media_service:
            logger.error(f"MediaStorageService not available for thumbnail {obj.id}")
            return None

        try:
            url = self._media_service.generate_presigned_url(
                obj.thumbnail_key,
                request_host=self._get_request_host(),
            )

            # Validate the URL was generated successfully
            if not url:
                logger.warning(
                    f"Thumbnail URL generation returned None for media {obj.id} "
                    f"with key {obj.thumbnail_key}"
                )
                # For thumbnails, we can gracefully degrade to no thumbnail
                return None

            return url

        except Exception as e:
            logger.error(
                f"Error generating thumbnail URL for media {obj.id}: {str(e)}",
                exc_info=True,  # Include stack trace for debugging
            )
            # For thumbnails, gracefully degrade to no thumbnail
            return None


